import React, { useEffect, useState } from 'react';
import { Link, Outlet, useLocation } from 'react-router-dom';
import { navigateToUrl } from 'single-spa';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { useResponsive } from '../../../hooks/useResponsive';
import { fetchUnreadCount } from '../../../store/slices/notificationSlice';
import { fetchUnreadMessageCount } from '../../../store/slices/messagesInboxSlice';
import { Topbar } from '../Topbar';
import { ErrorBoundary } from '../ErrorBoundary';
import {
  NotificationCenter,
  MessageCenter,
  AppSwitcher,
  AppDef,
  AppId,
  SwitchCompanyModal,
  getAuthUser,
} from '@linm-soft-org/linm-web-common-components';
import { signalRService } from '../../../services/signalr';
import { UserRole } from '../../../models/User';
import { showDevNav, isStandalone } from '../../../dev/isStandalone';
import { isScykShellPath, scykRoutes } from '../../../config/scykRoutes';
import { reconcileActiveCompanyForUser } from '../../../utils/reconcileActiveCompany';
import styles from './AppLayout.module.css';

const getActiveApp = (pathname: string): AppId => {
  if (isScykShellPath(pathname)) return 'medical-incidents';
  return 'task-management';
};

export const AppLayout: React.FC = () => {
  const location = useLocation();
  const dispatch = useAppDispatch();
  const currentUser = useAppSelector((state) => state.auth.user);

  const { isMobile } = useResponsive();
  const [isSwitchCompanyOpen, setIsSwitchCompanyOpen] = useState(false);

  useEffect(() => {
    if (!currentUser?.id || isStandalone) return;
    dispatch(fetchUnreadCount());
    dispatch(fetchUnreadMessageCount());
  }, [currentUser?.id, dispatch]);

  useEffect(() => {
    if (!currentUser?.id || isStandalone) return;
    return signalRService.onReconnected(() => {
      dispatch(fetchUnreadCount());
      dispatch(fetchUnreadMessageCount());
    });
  }, [currentUser?.id, dispatch]);

  useEffect(() => {
    if (isStandalone) return;
    const handler = () => {
      if (document.visibilityState === 'visible' && currentUser?.id) {
        dispatch(fetchUnreadCount());
      }
    };
    document.addEventListener('visibilitychange', handler);
    return () => document.removeEventListener('visibilitychange', handler);
  }, [currentUser?.id, dispatch]);

  // Tenant boundary: align X-Company-Id storage with JWT home + allowed_company_ids.
  useEffect(() => {
    if (isStandalone) return;
    reconcileActiveCompanyForUser(getAuthUser() ?? currentUser);
  }, [
    currentUser?.id,
    currentUser?.companyId,
    currentUser?.canViewAllCompanies,
    currentUser?.allowedCompanyIds?.join(','),
  ]);

  const activeApp = getActiveApp(location.pathname);

  const handleAppSwitch = (app: AppDef) => navigateToUrl(app.homeRoute);
  const handleShellNavigate = (path: string) => navigateToUrl(path);

  const getPageTitle = () => {
    const path = location.pathname;
    if (path === scykRoutes.incidents.list) return 'Danh Sách Sự Cố';
    if (path === scykRoutes.incidents.new) return 'Báo Cáo Sự Cố Mới';
    if (path === scykRoutes.dailyReports.list) return 'Báo Cáo Hàng Ngày';
    if (path === scykRoutes.dailyReports.new) return 'Báo Cáo Hàng Ngày Mới';
    if (path === scykRoutes.monthlyReports.list) return 'Báo Cáo Tổng Hợp Hàng Tháng';
    if (path === scykRoutes.monthlyReports.new) return 'Báo Cáo Tổng Hợp Mới';
    if (path.startsWith('/scyk/bc/tong-hop-thang/')) return 'Báo Cáo Tổng Hợp Hàng Tháng';
    if (path === scykRoutes.reports.summary) return 'Báo Cáo Thống Kê';
    if (path === scykRoutes.reports.serviceMismatch) return 'Báo Cáo Nhầm Dịch Vụ';
    if (path === scykRoutes.reports.fall) return 'Báo Cáo Sự Cố Té Ngã';
    if (path.startsWith('/scyk/su-co/')) return 'Chi Tiết Sự Cố';
    if (path === scykRoutes.fallWarnings.list) return 'Cảnh Báo Té Ngã';
    if (path === scykRoutes.fallWarnings.new) return 'Thêm Cảnh Báo Té Ngã';
    if (path.startsWith('/scyk/canh-bao/te-nga/')) return 'Chi Tiết Cảnh Báo Té Ngã';
    if (path.startsWith('/dev')) return 'Dev Navigation';
    return activeApp === 'medical-incidents' ? 'QLCV & SC Y Khoa' : 'Quản lý công việc';
  };

  return (
    <div className={`${styles.main} ${isStandalone ? styles.mainStandalone : styles.mainEmbedded}`} data-modal-root>
      <Topbar
        title={getPageTitle()}
        onSearch={() => {}}
        showMenuButton={isMobile}
        onMenuClick={() => window.dispatchEvent(new CustomEvent('linm:nav:toggle-mobile'))}
        notificationSlot={isStandalone ? undefined : (
          <NotificationCenter onNavigate={handleShellNavigate} />
        )}
        rightSlot={
          <>
            {showDevNav && !location.pathname.startsWith('/dev') && (
              <Link to="/dev" className={styles.devLink} title="Dev Navigation">
                <i className="fas fa-wrench" aria-hidden />
              </Link>
            )}
            {currentUser?.role === UserRole.Admin && (
              <button
                className={styles.switchCompanyBtn}
                onClick={() => setIsSwitchCompanyOpen(true)}
                title="Chuyển đổi công ty"
                aria-label="Chuyển đổi công ty"
              >
                <i className="fas fa-exchange-alt" />
                {!isMobile && <span className={styles.switchCompanyLabel}>Đổi công ty</span>}
              </button>
            )}
            {!isStandalone && <MessageCenter onNavigate={handleShellNavigate} />}
          </>
        }
        leftSlot={
          <AppSwitcher
            activeApp={activeApp}
            onSwitch={handleAppSwitch}
          />
        }
      />
      {currentUser?.role === UserRole.Admin && (
        <SwitchCompanyModal
          isOpen={isSwitchCompanyOpen}
          onClose={() => setIsSwitchCompanyOpen(false)}
        />
      )}
      <div className={styles.content}>
        <ErrorBoundary>
          <Outlet />
        </ErrorBoundary>
      </div>
    </div>
  );
};

export default AppLayout;
