/**
 * MonthlyReportEditor — full editor for monthly incident recommendation report.
 *
 * 4 sections:
 *   Mục 1 — Tổng hợp     : read-only summary (period / counts / departments / cause table)
 *   Mục 2 — Phân tích    : 3 charts + editable analysis texts (always mounted for base64 capture)
 *   Mục 3 — Trầm trọng   : RPN scoring per incident (incidentName + S/O/D)
 *   Mục 4 — Đề xuất      : causeDetail + solution per incident
 */
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { useReactToPrint } from 'react-to-print';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import { Doughnut, Bar } from 'react-chartjs-2';
import { Button, Modal, useDirtyTracking } from '@linm-soft-org/linm-web-common-components';
import {
  MedicalIncidentReport,
  MedicalIncidentReportFilters,
  IncidentReportSummaryItem,
  MonthlyIncidentReportDraft,
} from '../../../models/MedicalIncident';
import { useAppToast } from '../../../hooks/useAppToast';
import {
  medicalIncidentsAiEndpoint,
  MEDICAL_INCIDENT_MONTHLY_REPORT_FEATURE,
} from '../../../services/medicalIncidentsAi/endpoint';
import type {
  AiCreditCheckResult,
  AiCreditPack,
  AiInsufficientCreditError,
} from '../../../services/medicalIncidentsAi/types';
import { buildAnalyzeRequest } from '../../../services/medicalIncidentsAi/types';
import { applyAiMonthlyReportDraft } from '../applyAiDraft';
import { appSettings } from '../../../config/appSettings';
import {
  isMedicalReportAiEnabled,
  shouldShowMedicalReportAiButton,
} from '../../../config/medicalReportAiMode';
import { medicalIncidentEndpoint } from '../../../services/medicalIncidents/endpoint';
import {
  CHART_COLORS,
  DOUGHNUT_OPTIONS,
  BAR_OPTIONS_VERTICAL,
  BAR_OPTIONS_HORIZONTAL,
} from '../../MedicalIncidentReportPage/chartUtils';
import {
  PrintableRecommendationDoc,
  RpnRow,
  ChartImages,
  AiAnalysisOverride,
} from './PrintableRecommendationDoc';
import s from './MonthlyReportEditor.module.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

// ─── types ────────────────────────────────────────────────────────────────────

type ChartDisplayType = 'doughnut' | 'bar-v' | 'bar-h';
export type MonthlyReportSectionTab = 'summary' | 'analysis' | 'rpn' | 'solution';

interface Props {
  report:  MedicalIncidentReport;
  filters: MedicalIncidentReportFilters;
  /** Parent-controlled section tab (standalone form page). */
  activeSection?: MonthlyReportSectionTab;
  onSectionChange?: (tab: MonthlyReportSectionTab) => void;
  /** Hide internal section tabs when parent renders them in sticky header. */
  hideSectionTabs?: boolean;
  /** Fired when the user selects a report period (both dates set). */
  onPeriodChange?: (dateFrom: string, dateTo: string, includeDraft: boolean) => void;
  /** BCSC idCode — read-only "Số BC" display. */
  reportCode?: string;
  onDraftMetaChange?: (meta: {
    code:           string;
    totalIncidents: number;
    aiDraftApplied: boolean;
  }) => void;
  onSaveSuccess?: (saved: MonthlyIncidentReportDraft) => void;
  /** Called when unsaved-changes state flips. */
  onDirtyChange?: (dirty: boolean) => void;
}

// ─── constants ─────────────────────────────────────────────────────────────────

const PAGE_STYLE = `
  @page {
    size: A4 portrait;
    margin: 20mm 15mm 20mm 30mm;
    background: white;
  }
  @media print {
    html, body {
      margin: 0 !important;
      padding: 0 !important;
      overflow: visible !important;
      height: auto !important;
      width: 100% !important;
      background: white !important;
    }
    body > div { zoom: 1 !important; background: white !important; }
  }
`;

const EMPTY_RPN_ROW = (): RpnRow => ({
  incidentName: '',
  causeDetail:  '',
  s: '',
  o: '',
  d: '',
  solution:     '',
});

const isNativeMobile = () =>
  typeof navigator !== 'undefined' &&
  /android|iphone|ipad|ipod/i.test(navigator.userAgent);

function getPeriodLabel(filters: MedicalIncidentReportFilters): string {
  if (filters.dateFrom && filters.dateTo) {
    const from = new Date(filters.dateFrom);
    const to   = new Date(filters.dateTo);
    if (from.getFullYear() === to.getFullYear() && from.getMonth() === to.getMonth())
      return `Tháng ${from.getMonth() + 1}/${from.getFullYear()}`;
    return `${from.toLocaleDateString('vi-VN')} – ${to.toLocaleDateString('vi-VN')}`;
  }
  if (filters.year) return `Năm ${filters.year}`;
  return 'Kỳ báo cáo';
}

function fmtDate(iso: string) {
  if (!iso) return '';
  const d = new Date(iso);
  return `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
}

function pct(count: number, total: number) {
  if (!total) return '0';
  return ((count / total) * 100).toFixed(1);
}

// ─── ChartTypeSelector ─────────────────────────────────────────────────────────

const CHART_TYPE_OPTIONS: { key: ChartDisplayType; icon: string; label: string }[] = [
  { key: 'doughnut', icon: 'fas fa-circle-notch', label: 'Tròn' },
  { key: 'bar-v',    icon: 'fas fa-chart-bar',    label: 'Cột dọc' },
  { key: 'bar-h',    icon: 'fas fa-grip-lines',   label: 'Cột ngang' },
];

const ChartTypeSelector: React.FC<{
  value: ChartDisplayType;
  onChange: (v: ChartDisplayType) => void;
}> = ({ value, onChange }) => (
  <div className={s.chartTypeSelector}>
    {CHART_TYPE_OPTIONS.map((opt) => (
      <button
        key={opt.key}
        type="button"
        className={`${s.chartTypeSelectorBtn} ${value === opt.key ? s.chartTypeSelectorBtnActive : ''}`}
        onClick={() => onChange(opt.key)}
        title={opt.label}
      >
        <i className={opt.icon} />
        <span>{opt.label}</span>
      </button>
    ))}
  </div>
);

// ─── DynamicChart — renders Doughnut or Bar based on type ─────────────────────

interface DynamicChartProps {
  type:      ChartDisplayType;
  labels:    string[];
  data:      number[];
  onCapture: (base64: string) => void;
}

const DynamicChart: React.FC<DynamicChartProps> = ({ type, labels, data, onCapture }) => {
  const chartRef = useRef<ChartJS>(null);

  const animationComplete = useCallback(() => {
    if (chartRef.current) {
      onCapture(chartRef.current.toBase64Image());
    }
  }, [onCapture]);

  const colors = data.map((_, i) => CHART_COLORS[i % CHART_COLORS.length]);

  const chartData = {
    labels,
    datasets: [{
      data,
      backgroundColor: colors,
      borderColor:     type === 'doughnut' ? '#fff' : colors,
      borderWidth:     type === 'doughnut' ? 2 : 1,
    }],
  };

  const baseOptions = type === 'doughnut'
    ? DOUGHNUT_OPTIONS
    : type === 'bar-v'
      ? BAR_OPTIONS_VERTICAL
      : BAR_OPTIONS_HORIZONTAL;

  const options = {
    ...baseOptions,
    animation: {
      ...(baseOptions as { animation?: object }).animation,
      onComplete: animationComplete,
    },
  };

  if (type === 'doughnut') {
    return (
      <Doughnut
        ref={chartRef as React.RefObject<ChartJS<'doughnut'>>}
        data={chartData as Parameters<typeof Doughnut>[0]['data']}
        options={options as Parameters<typeof Doughnut>[0]['options']}
      />
    );
  }

  return (
    <Bar
      ref={chartRef as React.RefObject<ChartJS<'bar'>>}
      data={chartData as Parameters<typeof Bar>[0]['data']}
      options={options as Parameters<typeof Bar>[0]['options']}
    />
  );
};

// ─── Main component ────────────────────────────────────────────────────────────

export const MonthlyReportEditor: React.FC<Props> = ({
  report,
  filters,
  activeSection: activeSectionProp,
  onSectionChange,
  hideSectionTabs = false,
  onPeriodChange,
  reportCode: reportCodeProp,
  onDraftMetaChange,
  onSaveSuccess,
  onDirtyChange,
}) => {
  const toast       = useAppToast();

  const { markDirty, markClean } = useDirtyTracking(onDirtyChange);
  const aiMode      = appSettings.medicalReportAiMode;
  const isAiEnabled = isMedicalReportAiEnabled(aiMode);
  const showAiButton = shouldShowMedicalReportAiButton(aiMode);
  const [nativeMob]  = useState(() => isNativeMobile());
  const printRef     = useRef<HTMLDivElement>(null);

  // ── Section state ──────────────────────────────────────────────────────────
  const [internalSection, setInternalSection] = useState<MonthlyReportSectionTab>('summary');
  const activeSection = activeSectionProp ?? internalSection;
  const setActiveSection = (tab: MonthlyReportSectionTab) => {
    if (onSectionChange) onSectionChange(tab);
    else setInternalSection(tab);
  };

  // ── Local date filter (independent from parent filters) ───────────────────
  const [localDateFrom, setLocalDateFrom] = useState(filters.dateFrom ?? '');
  const [localDateTo,   setLocalDateTo]   = useState(filters.dateTo   ?? '');
  const [localIncludeDraft, setLocalIncludeDraft] = useState(filters.includeDraft ?? false);

  useEffect(() => {
    if (filters.dateFrom) setLocalDateFrom(filters.dateFrom);
    if (filters.dateTo) setLocalDateTo(filters.dateTo);
    if (filters.includeDraft !== undefined) setLocalIncludeDraft(filters.includeDraft);
  }, [filters.dateFrom, filters.dateTo, filters.includeDraft]);

  // effective dates used by all API calls
  const effectiveDateFrom = localDateFrom || filters.dateFrom || '';
  const effectiveDateTo   = localDateTo   || filters.dateTo   || '';
  const effectiveIncludeDraft = localIncludeDraft;

  // ── Draft load/save state ─────────────────────────────────────────────────
  const [draftLoading, setDraftLoading] = useState(false);
  const [draftSaving,  setDraftSaving]  = useState(false);
  const [loadedCode,   setLoadedCode]   = useState('');

  // ── Per-incident summary (Section 1 table) ────────────────────────────────
  const [summaryItems, setSummaryItems]     = useState<IncidentReportSummaryItem[]>([]);
  const [summaryLoading, setSummaryLoading] = useState(false);

  // ── RPN rows (Mục 3 & 4) ──────────────────────────────────────────────────
  const [rpnRows, setRpnRows] = useState<RpnRow[]>(() => [EMPTY_RPN_ROW()]);

  // ── Section 1 data (computed once from report) ────────────────────────────
  const voluntaryCount = report.byReportType.find((x) => x.key === 'voluntary')?.count ?? 0;
  const mandatoryCount = report.byReportType.find((x) => x.key === 'mandatory')?.count ?? 0;
  const departments    = report.byReportingDepartment.filter((d) => d.count > 0);
  const clinicalCount  = report.byIncidentTypeGroup.find((x) => x.key === 'group1')?.count ?? 0;
  const infraCount     = report.byIncidentTypeGroup.find((x) => x.key === 'group8')?.count ?? 0;
  const fallCount      = report.byIncidentTypeGroup.find((x) => x.key === 'group7')?.count ?? 0;
  const serviceCount   = Math.max(0, report.totalCount - clinicalCount - infraCount - fallCount);

  // ── Analysis texts (Mục 2) ────────────────────────────────────────────────
  const totalTypeGroups  = report.byIncidentTypeGroup.reduce((a, b) => a + b.count, 0) || 1;
  const totalOccurrence  = report.byOccurrenceStatus.reduce((a, b) => a + b.count, 0) || 1;
  const totalCauseGroups = report.byCauseGroup.reduce((a, b) => a + b.count, 0) || 1;
  const activeTypeGroups  = report.byIncidentTypeGroup.filter((x) => x.count > 0);
  const activeCauseGroups = report.byCauseGroup.filter((x) => x.count > 0);
  const ncGroups = report.byOccurrenceStatus.length ? report.byOccurrenceStatus : report.bySeverity;

  const [typeGroupText, setTypeGroupText] = useState(() => {
    const top = activeTypeGroups[0];
    if (!top) return '';
    return `Trong số các sự cố, sự cố liên quan đến "${top.label}" chiếm tỷ lệ cao nhất với ${pct(top.count, totalTypeGroups)}%.`;
  });

  const [occurrenceText, setOccurrenceText] = useState(() => {
    const nc0 = ncGroups.find((x) => x.key === 'not_occurred' || x.key === 'NC0');
    const nc1 = ncGroups.find((x) => x.key === 'occurred' || x.key === 'mild' || x.key === 'NC1');
    if (nc0) {
      return `Các sự cố chưa xảy ra (NC0) chiếm ${pct(nc0.count, totalOccurrence)}%${nc1 ? `, sự cố gây tổn thương nhẹ (NC1) chiếm ${pct(nc1.count, totalOccurrence)}%` : ''}.`;
    }
    return '';
  });

  const [causeGroupText, setCauseGroupText] = useState(() => {
    const top = activeCauseGroups[0];
    if (!top) return '';
    return `Nguyên nhân gây ra sự cố chủ yếu từ "${top.label}" chiếm ${pct(top.count, totalCauseGroups)}%.`;
  });

  // ── Chart types ────────────────────────────────────────────────────────────
  const [typeGroupChartType,  setTypeGroupChartType]  = useState<ChartDisplayType>('doughnut');
  const [occurrenceChartType, setOccurrenceChartType] = useState<ChartDisplayType>('doughnut');
  const [causeGroupChartType, setCauseGroupChartType] = useState<ChartDisplayType>('doughnut');

  // ── Chart images (captured by DynamicChart.onComplete) ────────────────────
  const [chartImages, setChartImages] = useState<ChartImages>({});

  const captureTypeGroup  = useCallback((b64: string) => setChartImages((p) => ({ ...p, typeGroup: b64 })), []);
  const captureOccurrence = useCallback((b64: string) => setChartImages((p) => ({ ...p, occurrence: b64 })), []);
  const captureCauseGroup = useCallback((b64: string) => setChartImages((p) => ({ ...p, causeGroup: b64 })), []);

  // ── Analysis override (AI text) ────────────────────────────────────────────
  const [analysisOverride, setAnalysisOverride] = useState<AiAnalysisOverride>({});

  // ── Preview ────────────────────────────────────────────────────────────────
  const [showPreview, setShowPreview] = useState(false);
  const previewScrollRef = useRef<HTMLDivElement>(null);
  const [zoom, setZoom] = useState(0.65);

  // ── AI ─────────────────────────────────────────────────────────────────────
  const [creditCheck,    setCreditCheck]    = useState<AiCreditCheckResult | null>(null);
  const [creditLoading,  setCreditLoading]  = useState(true);
  const [aiLoading,      setAiLoading]      = useState(false);
  const [showCreditModal, setShowCreditModal] = useState(false);
  const [suggestedPacks,  setSuggestedPacks]  = useState<AiCreditPack[]>([]);
  const [aiDraftApplied, setAiDraftApplied] = useState(false);

  const loadCreditCheck = useCallback(async () => {
    setCreditLoading(true);
    try {
      const check = await medicalIncidentsAiEndpoint.checkCredits(MEDICAL_INCIDENT_MONTHLY_REPORT_FEATURE);
      setCreditCheck(check);
      if (!check.canUse) setSuggestedPacks(check.suggestedPackages ?? []);
    } catch (error) {
      console.warn('[AI] credit check failed', error);
      setCreditCheck(null);
    } finally {
      setCreditLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!isAiEnabled) { setCreditLoading(false); return; }
    const t = setTimeout(() => { void loadCreditCheck(); }, 0);
    return () => clearTimeout(t);
  }, [loadCreditCheck, isAiEnabled]);

  // ── Load per-incident summary for Section 1 table ────────────────────────
  useEffect(() => {
    if (!effectiveDateFrom || !effectiveDateTo) return;
    let cancelled = false;
    setSummaryLoading(true);
    const t = setTimeout(async () => {
      try {
        const items = await medicalIncidentEndpoint.getReportSummary(
          effectiveDateFrom,
          effectiveDateTo,
          effectiveIncludeDraft,
        );
        if (!cancelled) setSummaryItems(items);
      } catch {
        // silently ignore
      } finally {
        if (!cancelled) setSummaryLoading(false);
      }
    }, 0);
    return () => { cancelled = true; clearTimeout(t); };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [effectiveDateFrom, effectiveDateTo, effectiveIncludeDraft]);

  // ── Load saved draft when period is known ─────────────────────────────────
  useEffect(() => {
    if (!effectiveDateFrom || !effectiveDateTo) return;
    let cancelled = false;
    setDraftLoading(true);
    const t = setTimeout(async () => {
      try {
        const draft = await medicalIncidentEndpoint.loadMonthlyReport(effectiveDateFrom, effectiveDateTo);
        if (cancelled || !draft) return;
        if (draft.typeGroupText)  setTypeGroupText(draft.typeGroupText);
        if (draft.occurrenceText) setOccurrenceText(draft.occurrenceText);
        if (draft.causeGroupText) setCauseGroupText(draft.causeGroupText);
        if (draft.typeGroupChartType)  setTypeGroupChartType(draft.typeGroupChartType as ChartDisplayType);
        if (draft.occurrenceChartType) setOccurrenceChartType(draft.occurrenceChartType as ChartDisplayType);
        if (draft.causeGroupChartType) setCauseGroupChartType(draft.causeGroupChartType as ChartDisplayType);
        if (draft.rpnRows?.length) {
          setRpnRows(draft.rpnRows.map((r) => ({
            incidentName: r.incidentName ?? '',
            causeDetail:  r.causeDetail  ?? '',
            s: r.s ?? '',
            o: r.o ?? '',
            d: r.d ?? '',
            solution: r.solution ?? '',
          })));
        }
        if (draft.code) setLoadedCode(draft.code);
        if (draft.aiDraftApplied) setAiDraftApplied(true);
        onDraftMetaChange?.({
          code:           draft.code,
          totalIncidents: draft.totalIncidents,
          aiDraftApplied: draft.aiDraftApplied,
        });
        markClean();
      } catch {
        // 404 = no draft yet
      } finally {
        if (!cancelled) setDraftLoading(false);
      }
    }, 0);
    return () => { cancelled = true; clearTimeout(t); };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [effectiveDateFrom, effectiveDateTo]);

  useEffect(() => {
    if (!effectiveDateFrom || !effectiveDateTo || !onPeriodChange) return;
    onPeriodChange(effectiveDateFrom, effectiveDateTo, effectiveIncludeDraft);
  }, [effectiveDateFrom, effectiveDateTo, effectiveIncludeDraft, onPeriodChange]);

  // ── Save draft ────────────────────────────────────────────────────────────
  const handleSaveDraft = async () => {
    if (!effectiveDateFrom || !effectiveDateTo) {
      toast.warning('Chọn kỳ báo cáo (từ ngày – đến ngày) trước khi lưu.');
      return;
    }
    setDraftSaving(true);
    try {
      const saved = await medicalIncidentEndpoint.saveMonthlyReport({
        dateFrom:            effectiveDateFrom,
        dateTo:              effectiveDateTo,
        reportNumber:        null,
        aiDraftApplied,
        totalIncidents:      report.totalCount,
        typeGroupText:       typeGroupText  || null,
        occurrenceText:      occurrenceText || null,
        causeGroupText:      causeGroupText || null,
        typeGroupChartType,
        occurrenceChartType,
        causeGroupChartType,
        rpnRows: rpnRows.map((r) => ({
          incidentName: r.incidentName,
          causeDetail:  r.causeDetail,
          s:            r.s !== '' ? Number(r.s) : null,
          o:            r.o !== '' ? Number(r.o) : null,
          d:            r.d !== '' ? Number(r.d) : null,
          solution:     r.solution,
        })),
      });
      onDraftMetaChange?.({
        code:           saved.code,
        totalIncidents: saved.totalIncidents,
        aiDraftApplied: saved.aiDraftApplied,
      });
      if (saved.code) setLoadedCode(saved.code);
      onSaveSuccess?.(saved);
      markClean();
      toast.success('Đã lưu bản nháp báo cáo');
    } catch (err) {
      toast.fromError(err, 'Lưu bản nháp thất bại');
    } finally {
      setDraftSaving(false);
    }
  };

  const handleAiAnalyze = async () => {
    if (creditCheck && !creditCheck.canUse) {
      setSuggestedPacks(creditCheck.suggestedPackages ?? []);
      setShowCreditModal(true);
      return;
    }
    setAiLoading(true);
    const requestId = crypto.randomUUID().replace(/-/g, '');
    try {
      const response = await medicalIncidentsAiEndpoint.analyzeReport(buildAnalyzeRequest(effectiveFilters), requestId);
      const applied = applyAiMonthlyReportDraft(response.result);
      setRpnRows(applied.rpnRows);
      setAnalysisOverride(applied.analysisOverride);
      if (applied.analysisOverride.typeGroupText)  setTypeGroupText(applied.analysisOverride.typeGroupText);
      if (applied.analysisOverride.occurrenceText) setOccurrenceText(applied.analysisOverride.occurrenceText);
      if (applied.analysisOverride.causeGroupText) setCauseGroupText(applied.analysisOverride.causeGroupText);
      setAiDraftApplied(true);
      markDirty();
      onDraftMetaChange?.({
        code:           reportCodeProp ?? loadedCode,
        totalIncidents: report.totalCount,
        aiDraftApplied: true,
      });
      setCreditCheck((prev) =>
        prev
          ? { ...prev, balance: response.balanceRemaining, canUse: response.balanceRemaining >= prev.requiredCredits }
          : prev,
      );
      toast.success('Đã tạo bản nháp AI — vui lòng rà soát trước khi in');
      if (applied.warnings.length > 0) toast.warning(applied.warnings[0]);
    } catch (error) {
      const insufficient = error as AiInsufficientCreditError;
      if (insufficient?.status === 402) {
        setSuggestedPacks(insufficient.data?.suggestedPackages ?? []);
        setShowCreditModal(true);
        return;
      }
      toast.fromError(error, 'Phân tích AI thất bại');
    } finally {
      setAiLoading(false);
    }
  };

  // ── Derived: effective filters + period label ─────────────────────────────
  const effectiveFilters = {
    ...filters,
    dateFrom: effectiveDateFrom || filters.dateFrom,
    dateTo:   effectiveDateTo   || filters.dateTo,
    includeDraft: effectiveIncludeDraft,
  };
  const periodLabel      = getPeriodLabel(effectiveFilters);
  const displayReportCode = reportCodeProp || loadedCode;

  // ── Print ──────────────────────────────────────────────────────────────────
  const handlePrint = useReactToPrint({
    content:       () => printRef.current,
    documentTitle: `BaoCao_${getPeriodLabel(effectiveFilters).replace(/\//g, '-')}`,
    pageStyle:     PAGE_STYLE,
  });

  const handleMobilePrint = () => {
    if (!printRef.current) return;
    const styleBlocks = Array.from(document.querySelectorAll('style')).map((el) => el.textContent || '').join('\n');
    const linkTags    = Array.from(document.querySelectorAll('link[rel="stylesheet"]')).map((el) => el.outerHTML).join('\n');
    const newWin = window.open('', '_blank');
    if (!newWin) { handlePrint(); return; }
    newWin.document.write(`<!DOCTYPE html><html><head>
      <meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
      <title>BaoCao_${getPeriodLabel(effectiveFilters)}</title>
      ${linkTags}<style>${PAGE_STYLE}</style><style>${styleBlocks}</style>
    </head><body style="margin:0;padding:0;background:white;">
      ${printRef.current.innerHTML}
    </body></html>`);
    newWin.document.close();
    newWin.focus();
    setTimeout(() => newWin.print(), 600);
  };

  const onPrintClick = () => (nativeMob ? handleMobilePrint() : handlePrint());

  const openPreview = () => {
    setShowPreview(true);
    setTimeout(() => {
      if (previewScrollRef.current)
        setZoom(Math.min(1, (previewScrollRef.current.clientWidth - 32) / 794));
    }, 50);
  };

  // ── RPN helpers ────────────────────────────────────────────────────────────
  const updateRpn = (idx: number, field: keyof RpnRow, value: string) => {
    markDirty();
    setRpnRows((prev) => prev.map((r, i) => i === idx ? { ...r, [field]: value } : r));
  };

  const addRpnRow = () => { markDirty(); setRpnRows((prev) => [...prev, EMPTY_RPN_ROW()]); };
  const removeRpnRow = (idx: number) => {
    markDirty();
    setRpnRows((prev) => prev.length > 1 ? prev.filter((_, i) => i !== idx) : prev);
  };
  const activeRpnCount = rpnRows.filter((r) => r.incidentName.trim()).length;

  const effectiveOverride: AiAnalysisOverride = {
    typeGroupText:  typeGroupText  || analysisOverride.typeGroupText,
    occurrenceText: occurrenceText || analysisOverride.occurrenceText,
    causeGroupText: causeGroupText || analysisOverride.causeGroupText,
  };

  // ── RPN color helper ───────────────────────────────────────────────────────
  function getRpnColor(rpn: number | null) {
    if (rpn === null) return '';
    return rpn >= 200 ? '#dc2626' : rpn >= 100 ? '#f59e0b' : '#10b981';
  }

  return (
    <div className={s.wrapper}>

      {/* ── Toolbar ─────────────────────────────────────────────────────────── */}
      <div className={s.toolbar}>
        <div className={s.toolbarInfo}>
          {draftLoading ? (
            <><i className="fas fa-spinner fa-spin" /><span>Đang tải bản lưu...</span></>
          ) : (
            <><i className="fas fa-lightbulb" />
            <span>
              <strong>{activeRpnCount}</strong> sự cố đã nhập · {periodLabel}
            </span></>
          )}
        </div>

        <div className={s.reportNumberWrapper}>
          <label className={s.reportNumberLabel}>Số BC:</label>
          <span className={s.reportCodeValue} title="Mã báo cáo tự sinh">
            {displayReportCode || '—'}
          </span>
        </div>

        <div className={s.toolbarActions}>
          <button
            className={s.btnSaveDraft}
            onClick={() => void handleSaveDraft()}
            disabled={draftSaving || !effectiveDateFrom || !effectiveDateTo}
            title={!effectiveDateFrom ? 'Chọn kỳ báo cáo để lưu' : 'Lưu bản nháp'}
          >
            <i className={`fas ${draftSaving ? 'fa-spinner fa-spin' : 'fa-save'}`} />
            <span>{draftSaving ? 'Đang lưu...' : 'Lưu bản nháp'}</span>
          </button>
          {showAiButton && isAiEnabled && (
            <button
              type="button"
              className={s.btnAiEnabled}
              data-testid="medical-report-ai-analyze-btn"
              disabled={aiLoading || creditLoading}
              onClick={() => void handleAiAnalyze()}
              title={
                creditCheck
                  ? `${creditCheck.balance} credit · cần ${creditCheck.requiredCredits}/lần`
                  : 'Phân tích AI'
              }
            >
              <i className={`fas ${aiLoading ? 'fa-spinner fa-spin' : 'fa-robot'}`} />
              <span>{aiLoading ? 'Đang phân tích...' : 'Phân tích với AI'}</span>
              {creditCheck && !creditLoading && (
                <span className={s.creditBadge}>{creditCheck.balance} credit</span>
              )}
            </button>
          )}
          {showAiButton && !isAiEnabled && (
            <button
              type="button"
              className={s.btnAi}
              data-testid="medical-report-ai-coming-soon-btn"
              disabled
              title="Tính năng phân tích AI sẽ được bật sau"
            >
              <i className="fas fa-robot" />
              <span>Phân tích với AI</span>
              <span className={s.aiComingSoon}>Sắp có</span>
            </button>
          )}
          {!nativeMob && (
            <button className={s.btnSecondary} onClick={openPreview}>
              <i className="fas fa-eye" /><span>Xem trước A4</span>
            </button>
          )}
          <button className={s.btnPrint} onClick={onPrintClick}>
            <i className={nativeMob ? 'fas fa-download' : 'fas fa-print'} />
            <span>{nativeMob ? 'Tải PDF' : 'In báo cáo'}</span>
          </button>
        </div>
      </div>

      {/* ── Filter bar — kỳ báo cáo ────────────────────────────────────────── */}
      <div className={s.filterBar}>
        <div className={s.filterBarLabel}>
          <i className="fas fa-calendar-alt" />
          Kỳ báo cáo:
        </div>
        <div className={s.filterBarGroup}>
          <label className={s.filterBarFieldLabel}>Từ ngày</label>
          <input
            className={s.filterDateInput}
            type="date"
            value={localDateFrom}
            onChange={(e) => setLocalDateFrom(e.target.value)}
          />
        </div>
        <div className={s.filterBarGroup}>
          <label className={s.filterBarFieldLabel}>Đến ngày</label>
          <input
            className={s.filterDateInput}
            type="date"
            value={localDateTo}
            onChange={(e) => setLocalDateTo(e.target.value)}
          />
        </div>
        {effectiveDateFrom && effectiveDateTo && (
          <span className={s.filterBarPeriodBadge}>
            <i className="fas fa-check-circle" style={{ color: '#10b981', marginRight: 4 }} />
            {periodLabel}
          </span>
        )}
        {(!effectiveDateFrom || !effectiveDateTo) && (
          <span className={s.filterBarHint}>Chọn kỳ để tải dữ liệu</span>
        )}
        {onPeriodChange && (
          <label className={s.filterBarDraftToggle}>
            <input
              type="checkbox"
              checked={localIncludeDraft}
              onChange={(e) => setLocalIncludeDraft(e.target.checked)}
            />
            Bao gồm sự cố nháp
          </label>
        )}
      </div>

      {isAiEnabled && aiDraftApplied && (
        <div className={s.aiDraftNotice} data-testid="medical-report-ai-draft-notice">
          <i className="fas fa-exclamation-triangle" />
          <span>
            Bản nháp AI đã được áp dụng. Rà soát và chỉnh sửa nội dung trước khi in hoặc trình ký.
          </span>
        </div>
      )}

      {!hideSectionTabs && (
        <div className={s.sectionTabs}>
          <button
            className={`${s.sectionTab} ${activeSection === 'summary' ? s.sectionTabActive : ''}`}
            onClick={() => setActiveSection('summary')}
          >
            <i className="fas fa-list-alt" /> Mục 1 — Tổng hợp
          </button>
          <button
            className={`${s.sectionTab} ${activeSection === 'analysis' ? s.sectionTabActive : ''}`}
            onClick={() => setActiveSection('analysis')}
          >
            <i className="fas fa-chart-pie" /> Mục 2 — Phân tích
          </button>
          <button
            className={`${s.sectionTab} ${activeSection === 'rpn' ? s.sectionTabActive : ''}`}
            onClick={() => setActiveSection('rpn')}
          >
            <i className="fas fa-exclamation-triangle" /> Mục 3 — Trầm trọng
          </button>
          <button
            className={`${s.sectionTab} ${activeSection === 'solution' ? s.sectionTabActive : ''}`}
            onClick={() => setActiveSection('solution')}
          >
            <i className="fas fa-lightbulb" /> Mục 4 — Đề xuất
          </button>
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════════════════
          MỤC 1 — Tổng hợp (read-only view of report data)
      ═══════════════════════════════════════════════════════════════════════ */}
      {activeSection === 'summary' && (
        <div className={s.summarySection}>
          {/* 1.1 Thời gian */}
          <div className={s.summaryCard}>
            <div className={s.summaryCardTitle}>
              <i className="fas fa-calendar-alt" style={{ color: '#0066cc' }} />
              1.1 Thời gian báo cáo
            </div>
            <div className={s.summaryRow}>
              <span className={s.summaryRowLabel}>Từ ngày:</span>
              <strong>{fmtDate(effectiveDateFrom) || '—'}</strong>
            </div>
            <div className={s.summaryRow}>
              <span className={s.summaryRowLabel}>Đến ngày:</span>
              <strong>{fmtDate(effectiveDateTo) || '—'}</strong>
            </div>
          </div>

          {/* 1.2 Số lượng báo cáo */}
          <div className={s.summaryCard}>
            <div className={s.summaryCardTitle}>
              <i className="fas fa-file-medical-alt" style={{ color: '#059669' }} />
              1.2 Số lượng báo cáo
            </div>
            <div className={s.summaryTotalRow}>
              Tổng: <strong className={s.summaryTotalNum}>{report.totalCount}</strong> sự cố / sai sót chuyên môn
            </div>
            <div className={s.summaryIndent}>
              <div className={s.summaryIndentRow}>
                <span className={s.summaryIndentBullet}>+</span>
                <span>Báo cáo tự nguyện:</span>
                <strong>{voluntaryCount}</strong> sự cố
              </div>
              <div className={s.summaryIndentRow}>
                <span className={s.summaryIndentBullet}>+</span>
                <span>Báo cáo bắt buộc:</span>
                <strong>{mandatoryCount}</strong> sự cố
              </div>
            </div>
          </div>

          {/* Tổng số khoa báo cáo */}
          <div className={s.summaryCard}>
            <div className={s.summaryCardTitle}>
              <i className="fas fa-hospital" style={{ color: '#7c3aed' }} />
              Khoa báo cáo ({departments.length} khoa)
            </div>
            {departments.length === 0 ? (
              <div className={s.summaryEmpty}>Chưa có dữ liệu khoa báo cáo</div>
            ) : (
              <div className={s.summaryDeptList}>
                {departments.map((d) => (
                  <div key={d.key} className={s.summaryDeptRow}>
                    <span className={s.summaryDeptName}>+ {d.label}</span>
                    <span className={s.summaryDeptCount}>{d.count} sự cố</span>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Tổng hợp theo nhóm sự cố */}
          <div className={s.summaryCard}>
            <div className={s.summaryCardTitle}>
              <i className="fas fa-layer-group" style={{ color: '#d97706' }} />
              Tổng hợp báo cáo sự cố
            </div>
            <div className={s.summaryIndent}>
              <div className={s.summaryIndentRow}>
                <span className={s.summaryIndentBullet}>+</span>
                <span>Sự cố liên quan quy trình chuyên môn:</span>
                <strong>{clinicalCount}</strong> sự cố
              </div>
              <div className={s.summaryIndentRow}>
                <span className={s.summaryIndentBullet}>+</span>
                <span>Sự cố liên quan cung cấp nhóm dịch vụ:</span>
                <strong>{serviceCount}</strong> sự cố
              </div>
              <div className={s.summaryIndentRow}>
                <span className={s.summaryIndentBullet}>+</span>
                <span>Sự cố té ngã:</span>
                <strong>{fallCount}</strong> sự cố
              </div>
            </div>
          </div>

          {/* Bảng chi tiết per-incident: Khoa | Sự cố/sai sót/nguy cơ | Nguyên nhân */}
          <div className={s.summaryCard}>
            <div className={s.summaryCardTitle}>
              <i className="fas fa-table" style={{ color: '#475569' }} />
              Chi tiết sự cố theo từng khoa
              {summaryLoading && (
                <span className={s.summaryPhaseNote}>
                  <i className="fas fa-spinner fa-spin" style={{ marginRight: 4 }} />Đang tải...
                </span>
              )}
              {!summaryLoading && summaryItems.length > 0 && (
                <span className={s.summaryPhaseNote}>({summaryItems.length} sự cố)</span>
              )}
            </div>
            <div className={s.summaryTableWrapper}>
              <table className={s.summaryTable}>
                <thead>
                  <tr>
                    <th style={{ width: '20%' }}>Khoa</th>
                    <th style={{ width: '42%' }}>Sự cố/ sai sót/ nguy cơ</th>
                    <th style={{ width: '38%' }}>Nguyên nhân</th>
                  </tr>
                </thead>
                <tbody>
                  {summaryItems.length > 0
                    ? summaryItems.map((item, idx) => (
                        <tr key={idx}>
                          <td className={s.summaryTableGroupCell}>{item.departmentName || '—'}</td>
                          <td>{item.briefDescription || '—'}</td>
                          <td style={{ fontStyle: item.causeDescription ? 'normal' : 'italic', color: item.causeDescription ? 'inherit' : '#94a3b8' }}>
                            {item.causeDescription || '(chưa có phân tích nguyên nhân)'}
                          </td>
                        </tr>
                      ))
                    : (
                      <tr>
                        <td colSpan={3} style={{ textAlign: 'center', fontStyle: 'italic', color: '#94a3b8', padding: '16px 8px' }}>
                          {summaryLoading
                            ? 'Đang tải dữ liệu...'
                            : (!effectiveDateFrom || !effectiveDateTo)
                              ? 'Chọn kỳ báo cáo để xem chi tiết sự cố'
                              : 'Không có sự cố trong kỳ này'}
                        </td>
                      </tr>
                    )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════════════════
          MỤC 2 — Phân tích
          Charts always mounted (hidden via CSS) for base64 capture
      ═══════════════════════════════════════════════════════════════════════ */}
      <div className={activeSection === 'analysis' ? undefined : s.sectionHidden}>

        {/* 2.1 Nhóm sự cố */}
        <div className={s.analysisSubsection}>
          <div className={s.analysisSubsectionHeader}>
            <div className={s.analysisSubsectionTitle}>
              <i className="fas fa-layer-group" style={{ color: CHART_COLORS[0] }} />
              2.1 Nhóm sự cố
              <span className={s.figLabel}>Hình 1</span>
            </div>
            <ChartTypeSelector value={typeGroupChartType} onChange={(v) => { markDirty(); setTypeGroupChartType(v); }} />
          </div>
          <div className={s.chartContainer}>
            {activeTypeGroups.length > 0 ? (
              <DynamicChart
                type={typeGroupChartType}
                labels={activeTypeGroups.map((x) => x.label)}
                data={activeTypeGroups.map((x) => x.count)}
                onCapture={captureTypeGroup}
              />
            ) : (
              <div className={s.chartEmpty}>Không có dữ liệu nhóm sự cố</div>
            )}
          </div>
          <div className={s.analysisTextWrapper}>
            <label className={s.analysisTextLabel}>
              <i className="fas fa-pen-alt" /> Nhận xét phân tích (có thể chỉnh sửa)
            </label>
            <textarea
              className={s.analysisTextarea}
              rows={3}
              value={typeGroupText}
              onChange={(e) => { markDirty(); setTypeGroupText(e.target.value); }}
              placeholder="Nhập nhận xét phân tích về nhóm sự cố..."
            />
          </div>
        </div>

        {/* 2.2 Hậu quả đối với người bệnh */}
        <div className={s.analysisSubsection}>
          <div className={s.analysisSubsectionHeader}>
            <div className={s.analysisSubsectionTitle}>
              <i className="fas fa-user-injured" style={{ color: CHART_COLORS[1] }} />
              2.2 Hậu quả đối với người bệnh
              <span className={s.figLabel}>Hình 2</span>
            </div>
            <ChartTypeSelector value={occurrenceChartType} onChange={(v) => { markDirty(); setOccurrenceChartType(v); }} />
          </div>
          <div className={s.chartContainer}>
            {ncGroups.length > 0 ? (
              <DynamicChart
                type={occurrenceChartType}
                labels={ncGroups.map((x) => x.label)}
                data={ncGroups.map((x) => x.count)}
                onCapture={captureOccurrence}
              />
            ) : (
              <div className={s.chartEmpty}>Không có dữ liệu hậu quả sự cố</div>
            )}
          </div>
          <div className={s.analysisTextWrapper}>
            <label className={s.analysisTextLabel}>
              <i className="fas fa-pen-alt" /> Nhận xét phân tích (có thể chỉnh sửa)
            </label>
            <textarea
              className={s.analysisTextarea}
              rows={3}
              value={occurrenceText}
              onChange={(e) => { markDirty(); setOccurrenceText(e.target.value); }}
              placeholder="Nhập nhận xét phân tích về hậu quả sự cố..."
            />
          </div>
        </div>

        {/* 2.3 Nhóm nguyên nhân */}
        <div className={s.analysisSubsection}>
          <div className={s.analysisSubsectionHeader}>
            <div className={s.analysisSubsectionTitle}>
              <i className="fas fa-sitemap" style={{ color: CHART_COLORS[2] }} />
              2.3 Nhóm nguyên nhân gây ra sự cố
              <span className={s.figLabel}>Hình 3</span>
            </div>
            <ChartTypeSelector value={causeGroupChartType} onChange={(v) => { markDirty(); setCauseGroupChartType(v); }} />
          </div>
          <div className={s.chartContainer}>
            {activeCauseGroups.length > 0 ? (
              <DynamicChart
                type={causeGroupChartType}
                labels={activeCauseGroups.map((x) => x.label)}
                data={activeCauseGroups.map((x) => x.count)}
                onCapture={captureCauseGroup}
              />
            ) : (
              <div className={s.chartEmpty}>Không có dữ liệu nhóm nguyên nhân</div>
            )}
          </div>
          <div className={s.analysisTextWrapper}>
            <label className={s.analysisTextLabel}>
              <i className="fas fa-pen-alt" /> Nhận xét phân tích (có thể chỉnh sửa)
            </label>
            <textarea
              className={s.analysisTextarea}
              rows={3}
              value={causeGroupText}
              onChange={(e) => { markDirty(); setCauseGroupText(e.target.value); }}
              placeholder="Nhập nhận xét phân tích về nhóm nguyên nhân..."
            />
          </div>
        </div>
      </div>

      {/* ═══════════════════════════════════════════════════════════════════════
          MỤC 3 — Trầm trọng (RPN scoring: incidentName + S/O/D only)
      ═══════════════════════════════════════════════════════════════════════ */}
      {activeSection === 'rpn' && (
        <div className={s.rpnSection}>
          <div className={s.rpnHeader}>
            <div className={s.rpnDescription}>
              <i className="fas fa-info-circle" style={{ color: '#3b82f6', marginRight: 6 }} />
              Nhập tên sự cố và điểm <strong>S × O × D</strong> (thang 1–10) để tính chỉ số RPN.
              Sau đó sang <strong>Mục 4</strong> để điền nguyên nhân và đề xuất.
            </div>
            <button className={s.btnAddRow} onClick={addRpnRow}>
              <i className="fas fa-plus" /> Thêm sự cố
            </button>
          </div>

          <div className={s.rpnCards}>
            {rpnRows.map((row, idx) => {
              const rpn =
                row.s !== '' && row.o !== '' && row.d !== ''
                  ? Number(row.s) * Number(row.o) * Number(row.d)
                  : null;
              const rpnColor = getRpnColor(rpn);

              return (
                <div key={idx} className={s.rpnCard}>
                  <div className={s.rpnCardHeader}>
                    <span className={s.rpnCardIndex}>{idx + 1}</span>
                    <input
                      className={s.rpnNameInput}
                      type="text"
                      placeholder="Tên sự cố y khoa..."
                      value={row.incidentName}
                      onChange={(e) => updateRpn(idx, 'incidentName', e.target.value)}
                    />
                    {rpn !== null && (
                      <span className={s.rpnBadge} style={{ background: rpnColor }}>
                        RPN {rpn}
                      </span>
                    )}
                    <button
                      className={s.rpnRemoveBtn}
                      onClick={() => removeRpnRow(idx)}
                      title="Xoá"
                    >
                      <i className="fas fa-times" />
                    </button>
                  </div>

                  <div className={s.rpnCardScores}>
                    {(['s', 'o', 'd'] as const).map((field) => (
                      <label key={field} className={s.rpnScoreLabel}>
                        <span className={s.rpnScoreKey}>{field.toUpperCase()}</span>
                        <input
                          className={s.rpnNumInput}
                          type="number"
                          min={1} max={10}
                          placeholder="1-10"
                          value={row[field]}
                          onChange={(e) => updateRpn(idx, field, e.target.value)}
                        />
                      </label>
                    ))}
                    <span className={s.rpnResult} style={{ color: rpnColor || '#94a3b8' }}>
                      = {rpn !== null ? <strong>{rpn}</strong> : '—'}
                    </span>
                    <span className={s.rpnScoreHint}>
                      S = Mức độ nghiêm trọng · O = Xác suất xảy ra · D = Khả năng phát hiện
                    </span>
                  </div>
                </div>
              );
            })}
          </div>

          <div className={s.rpnLegend}>
            <span style={{ color: '#dc2626' }}>■ ≥ 200: Ưu tiên cao</span>
            <span style={{ color: '#f59e0b' }}>■ 100–199: Cần theo dõi</span>
            <span style={{ color: '#10b981' }}>■ &lt; 100: Thấp</span>
          </div>
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════════════════
          MỤC 4 — Đề xuất (causeDetail + solution per incident)
      ═══════════════════════════════════════════════════════════════════════ */}
      {activeSection === 'solution' && (
        <div className={s.solutionSection}>
          {rpnRows.filter((r) => r.incidentName.trim()).length === 0 ? (
            <div className={s.solutionEmpty}>
              <i className="fas fa-arrow-left" style={{ marginRight: 8 }} />
              Vào <strong>Mục 3 — Trầm trọng</strong> nhập tên sự cố trước, sau đó quay lại đây để điền nguyên nhân và đề xuất.
            </div>
          ) : (
            <>
              <div className={s.solutionHeader}>
                <div className={s.solutionDescription}>
                  <i className="fas fa-info-circle" style={{ color: '#3b82f6', marginRight: 6 }} />
                  Nhập nguyên nhân chi tiết và đề xuất giải pháp cho từng sự cố.
                  Sẽ in ở <strong>Mục 4</strong> của báo cáo (cột trái: nguyên nhân, cột phải: giải pháp).
                </div>
              </div>

              <div className={s.solutionCards}>
                {rpnRows.map((row, idx) => {
                  if (!row.incidentName.trim()) return null;
                  const rpn =
                    row.s !== '' && row.o !== '' && row.d !== ''
                      ? Number(row.s) * Number(row.o) * Number(row.d)
                      : null;
                  const rpnColor = getRpnColor(rpn);

                  return (
                    <div key={idx} className={s.solutionCard}>
                      <div className={s.solutionCardHeader}>
                        <span className={s.solutionCardIndex}>{idx + 1}</span>
                        <span className={s.solutionCardTitle}>{row.incidentName}</span>
                        {rpn !== null && (
                          <span className={s.rpnBadge} style={{ background: rpnColor, marginLeft: 'auto' }}>
                            RPN {rpn}
                          </span>
                        )}
                      </div>
                      <div className={s.solutionCardBody}>
                        <div className={s.solutionCardField}>
                          <label className={s.solutionFieldLabel}>
                            <i className="fas fa-exclamation-triangle" style={{ color: '#f59e0b' }} />
                            Nguyên nhân chi tiết
                            <span className={s.solutionFieldHint}>(cột trái Mục 4)</span>
                          </label>
                          <textarea
                            className={s.solutionCauseInput}
                            rows={4}
                            placeholder="Mô tả nguyên nhân cụ thể gây ra sự cố này..."
                            value={row.causeDetail}
                            onChange={(e) => updateRpn(idx, 'causeDetail', e.target.value)}
                          />
                        </div>
                        <div className={s.solutionCardField}>
                          <label className={s.solutionFieldLabel}>
                            <i className="fas fa-lightbulb" style={{ color: '#10b981' }} />
                            Đề xuất giải pháp
                            <span className={s.solutionFieldHint}>(cột phải Mục 4)</span>
                          </label>
                          <textarea
                            className={s.solutionSolutionInput}
                            rows={5}
                            placeholder={`Nhập đề xuất giải pháp phòng ngừa...\n\nVí dụ:\n- Tổ chức đào tạo lại quy trình\n- Tăng cường kiểm tra định kỳ`}
                            value={row.solution}
                            onChange={(e) => updateRpn(idx, 'solution', e.target.value)}
                          />
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </>
          )}
        </div>
      )}

      {/* ── Hidden A4 print target ───────────────────────────────────────────── */}
      <div className={s.printHidden}>
        <PrintableRecommendationDoc
          ref={printRef}
          report={report}
          filters={effectiveFilters}
          rpnRows={rpnRows}
          chartImages={chartImages}
          reportCode={displayReportCode || undefined}
          analysisOverride={effectiveOverride}
          aiDraftLabel={aiDraftApplied}
          summaryItems={summaryItems}
        />
      </div>

      {/* ── A4 Preview modal ─────────────────────────────────────────────────── */}
      {showPreview && (
        <div className={s.previewOverlay} onClick={() => setShowPreview(false)}>
          <div className={s.previewModal} onClick={(e) => e.stopPropagation()}>
            <div className={s.previewModalHeader}>
              <span>
                <i className="fas fa-eye" style={{ marginRight: 6 }} />
                Xem trước A4 — {periodLabel}
              </span>
              <div style={{ display: 'flex', gap: 8 }}>
                <button className={s.btnPrint} onClick={onPrintClick}>
                  <i className="fas fa-print" /> In / Lưu PDF
                </button>
                <button className={s.previewCloseBtn} onClick={() => setShowPreview(false)}>
                  <i className="fas fa-times" />
                </button>
              </div>
            </div>
            <div className={s.previewScroll} ref={previewScrollRef}>
              <div style={{ zoom }}>
                <PrintableRecommendationDoc
                  report={report}
                  filters={effectiveFilters}
                  rpnRows={rpnRows}
                  chartImages={chartImages}
                  reportCode={displayReportCode || undefined}
                  analysisOverride={effectiveOverride}
                  aiDraftLabel={aiDraftApplied}
                  summaryItems={summaryItems}
                />
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ── AI Credit modal ──────────────────────────────────────────────────── */}
      {isAiEnabled && (
        <Modal
          isOpen={showCreditModal}
          onClose={() => setShowCreditModal(false)}
          title="Không đủ credit AI"
          size="sm"
          data-testid="medical-report-ai-credit-modal"
        >
          <div className={s.creditModalBody}>
            <p className={s.creditModalIntro}>
              Phân tích báo cáo SCYK cần{' '}
              <strong>{creditCheck?.requiredCredits ?? 20} credit</strong>
              {creditCheck != null && (
                <> — bạn còn <strong>{creditCheck.balance}</strong> credit.</>
              )}
            </p>
            <div className={s.creditPackList}>
              {(suggestedPacks.length > 0 ? suggestedPacks : creditCheck?.suggestedPackages ?? []).map(
                (pack) => (
                  <div
                    key={pack.packId}
                    className={`${s.creditPackItem} ${pack.recommended ? s.creditPackItemRecommended : ''}`}
                  >
                    <div>
                      <span className={s.creditPackLabel}>{pack.label}</span>
                      {pack.recommended && <span className={s.creditPackTag}>Đề xuất</span>}
                    </div>
                    <span className={s.creditPackPrice}>
                      {pack.priceVnd.toLocaleString('vi-VN')} ₫
                    </span>
                  </div>
                ),
              )}
            </div>
            <Button variant="secondary" onClick={() => setShowCreditModal(false)}>
              Đóng
            </Button>
          </div>
        </Modal>
      )}
    </div>
  );
};
