import { getAuthUser } from '@linm-soft-org/linm-web-common-components';
import { isStandalone } from '../dev/isStandalone';
import { seedStandaloneAuth } from '../standalone/mockAuth';
import { reconcileActiveCompanyForUser } from '../utils/reconcileActiveCompany';

function bindTenantReconcileOnAuthChange(): void {
  if (typeof window === 'undefined' || isStandalone) return;
  window.addEventListener('linm:auth:changed', () => {
    reconcileActiveCompanyForUser(getAuthUser());
  });
  window.addEventListener('linm:company:changed', () => {
    reconcileActiveCompanyForUser(getAuthUser());
  });
}

/**
 * Run before first render so X-Company-Id is valid before list/API effects fire.
 */
export function bootstrapTenantContext(): void {
  if (isStandalone) {
    // Clear shell/prod session so DevAuth + UBNA tenant apply locally.
    seedStandaloneAuth(true);
    return;
  }

  reconcileActiveCompanyForUser(getAuthUser());
  bindTenantReconcileOnAuthChange();
}
