import {
  clearActiveCompanyId,
  getActiveCompanyId,
  getAuthUser,
  isTenantSwitchAllowed,
  resolveInitialActiveCompanyId,
  setActiveCompanyId,
  setAuthUser,
} from '@linm-soft-org/linm-web-common-components';
import type { User } from '../models/User';
import { readJwtHomeCompanyId, readJwtTenantScope } from './jwtTenantClaims';

function normCompanyCode(value: string): string {
  return value.trim().toUpperCase();
}

/**
 * TENANT-P1-03 — JWT `company_id` + `allowed_company_ids` override stale user blob
 * (e.g. persisted `LINM` while token home is `UBNA`).
 */
function resolveTenantScope(user: User | null | undefined): {
  homeCode: string | undefined;
  allowedCompanyIds: string[] | undefined;
  canViewAll: boolean;
} {
  const jwtHome = readJwtHomeCompanyId();
  const jwtScope = readJwtTenantScope();
  const scopedUser = user ?? getAuthUser();

  const homeCode = jwtHome ?? (scopedUser?.companyId ? normCompanyCode(scopedUser.companyId) : undefined);
  const allowedCompanyIds = jwtScope.allowedCompanyIds.length > 0
    ? jwtScope.allowedCompanyIds
    : scopedUser?.allowedCompanyIds?.map(normCompanyCode);
  const canViewAll = jwtScope.canViewAll || scopedUser?.canViewAllCompanies === true;

  return { homeCode, allowedCompanyIds, canViewAll };
}

/** Patch secure-storage user when JWT home differs from cached `companyId`. */
function syncUserHomeFromJwt(user: User | null | undefined): User | null | undefined {
  const jwtHome = readJwtHomeCompanyId();
  const jwtScope = readJwtTenantScope();
  const scopedUser = user ?? getAuthUser();
  if (!jwtHome || !scopedUser) return scopedUser;

  if (scopedUser.companyId && normCompanyCode(scopedUser.companyId) === jwtHome) {
    return scopedUser;
  }

  const updated: User = {
    ...scopedUser,
    companyId: jwtHome,
    allowedCompanyIds: jwtScope.allowedCompanyIds.length > 0
      ? jwtScope.allowedCompanyIds
      : scopedUser.allowedCompanyIds,
    canViewAllCompanies: jwtScope.canViewAll || scopedUser.canViewAllCompanies,
  };
  setAuthUser(updated);
  return updated;
}

/**
 * Align `linm_active_company_id` (X-Company-Id) with JWT home + allowed_company_ids.
 * Call synchronously on app boot — before list pages fire API calls.
 */
export function reconcileActiveCompanyForUser(user: User | null | undefined): void {
  const syncedUser = syncUserHomeFromJwt(user);
  const { homeCode, allowedCompanyIds, canViewAll } = resolveTenantScope(syncedUser);

  if (!homeCode) {
    if (getActiveCompanyId()) {
      clearActiveCompanyId();
    }
    return;
  }

  const active = getActiveCompanyId();

  if (active && !isTenantSwitchAllowed(active, canViewAll, allowedCompanyIds, homeCode)) {
    setActiveCompanyId(homeCode);
    return;
  }

  const initial = resolveInitialActiveCompanyId(
    homeCode,
    allowedCompanyIds,
    canViewAll,
  );

  if (initial && initial !== active) {
    setActiveCompanyId(initial);
    return;
  }

  if (!active) {
    setActiveCompanyId(homeCode);
  }
}
